const SB='https://ulylpdeutafjuuevdllz.supabase.co';
const KEY='sb_publishable_rygFKvTzyxTvn9SfTHcYdA_tEeS6OTH';
const API=SB+'/functions/v1/cuadros-service';
const $=(s)=>document.querySelector(s);
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-EC',{style:'currency',currency:'USD'}).format(Number(n||0)/100);
const date=(d,full=true)=>new Intl.DateTimeFormat('es-EC',{timeZone:'America/Guayaquil',day:'numeric',month:'short',...(full?{hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(d));
const time=()=>S.data?.server_time?Date.now()+S.offset:Date.now();
const stateName={scheduled:'Programado',open:'Inscripciones abiertas',closed:'Inscripciones cerradas',active:'En marcha',finished:'Finalizado'};
const S={session:JSON.parse(localStorage.getItem('cuadros-session')||'null'),data:null,route:'explore',filter:'all',adminTab:'cuadros',authMode:'login',detail:null,offset:0,busy:false};
let installPrompt=null,lastFocus=null;
const navs=[['explore','▦','Explorar'],['mine','◈','Mis cuadros'],['prizes','✧','Sorteos'],['notices','♧','Avisos'],['profile','◉','Mi cuenta']];
const admin=()=>S.data?.profile.role==='admin';
const formObj=f=>Object.fromEntries(new FormData(f));
const dollars=x=>Math.round(Number(x)*100);
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
async function auth(path,body,method='POST'){const r=await fetch(SB+'/auth/v1/'+path,{method,headers:{apikey:KEY,'Content-Type':'application/json',...(S.session?{Authorization:'Bearer '+S.session.access_token}:{})},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.msg||d.error_description||d.message||'No se pudo iniciar sesión');return d}
function saveSession(s){S.session=s;localStorage.setItem('cuadros-session',JSON.stringify(s))}
async function ensureSession(){if(S.session&&S.session.expires_at*1000<Date.now()+60000){try{saveSession(await auth('token?grant_type=refresh_token',{refresh_token:S.session.refresh_token}))}catch{localStorage.removeItem('cuadros-session');S.session=null;S.data=null;render();throw Error('Tu sesión terminó. Inicia sesión nuevamente.')}}}
async function api(action,data={},anonymous=false){if(!anonymous)await ensureSession();const r=await fetch(API,{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json',...(!anonymous&&S.session?{Authorization:'Bearer '+S.session.access_token}:{})},body:JSON.stringify({action,...data})});const d=await r.json();if(!r.ok)throw Error(d.error||'No se pudo completar la operación');return d}
async function load(){if(!S.session)return render();S.data=await api('snapshot');if(S.data.server_time)S.offset=+new Date(S.data.server_time)-Date.now();render();}
function setRoute(r){S.route=r;S.detail=null;S.filter='all';render();window.scrollTo({top:0,behavior:'instant'})}
function closeModal(){$('#modal-root').innerHTML='';lastFocus?.focus()}
function modal(title,content,footer=''){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modalback"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalhead"><h2>${esc(title)}</h2><button class="iconbtn" data-act="close" aria-label="Cerrar">×</button></div>${content}${footer?`<footer>${footer}</footer>`:''}</section></div>`;setTimeout(()=>$('#modal-root input, #modal-root button')?.focus(),0)}
function head(title,subtitle='',action=''){return `<div class="pagehead"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`}
function empty(title,desc,button=''){return `<div class="empty"><span class="emptyicon">▦</span><h2>${title}</h2><p>${desc}</p>${button}</div>`}
function bankFields(b={}){return `<label class="field">Banco<input name="bank" required maxlength="80" value="${esc(b.bank)}" placeholder="Ej. Banco Pichincha"></label><label class="field">Tipo de cuenta<select name="account_type"><option ${b.account_type==='Ahorros'?'selected':''}>Ahorros</option><option ${b.account_type==='Corriente'?'selected':''}>Corriente</option></select></label><label class="field">Número de cuenta<input name="account_number" required inputmode="numeric" pattern="[0-9]{4,30}" value="${esc(b.account_number)}" autocomplete="off"></label><label class="field">Titular<input name="holder" required value="${esc(b.holder)}" maxlength="160"></label><label class="field">Cédula del titular<input name="bank_identity" value="${esc(b.identity_number)}" maxlength="30" inputmode="numeric"></label><label class="field">Correo del titular<input name="bank_email" type="email" value="${esc(b.email)}" maxlength="254"></label>`}
function renderAuth(){const reg=S.authMode==='register';$('#app').innerHTML=`<main class="auth"><section class="authart"><div class="row"><span class="logo">▦</span><span class="brand">Cuadros<small>POR BILLY</small></span></div><div><h1>Un aporte.<br>Una semana.<br><span class="accent">Tu turno.</span></h1><p class="spacer">Tus cuadros y comprobantes, en un solo lugar. Sigue cada semana hasta llegar a tu turno.</p></div><div class="authsteps"><div class="authstep"><strong>01</strong>Elige un cuadro</div><div class="authstep"><strong>02</strong>Aporta cada semana</div><div class="authstep"><strong>03</strong>Recibe tu turno</div></div></section><section class="authform"><div class="authinner"><h2>${reg?'Solicita tu cuenta':'Bienvenido de nuevo'}</h2><p class="muted">${reg?'Billy revisará tu solicitud antes de que puedas participar.':'Entra para consultar tus cuadros y próximos aportes.'}</p><form id="auth-form"><div class="formgrid">${reg?`<label class="field full">Nombre completo<input name="name" autocomplete="name" required maxlength="160"></label><label class="field">Cédula<input name="identity_number" required maxlength="30" inputmode="numeric"></label><label class="field">Celular<input name="phone" type="tel" autocomplete="tel" required maxlength="30"></label><label class="field full">Empresa o referencia<input name="company" maxlength="160"></label>`:''}<label class="field full">Correo electrónico<input name="email" type="email" autocomplete="username" required></label><label class="field full">Contraseña<input name="password" type="password" autocomplete="${reg?'new-password':'current-password'}" required minlength="${reg?10:1}">${reg?'<span class="muted tiny">Al menos 10 caracteres.</span>':''}</label>${reg?`<h3 class="field full">Tu cuenta bancaria principal</h3>${bankFields()}<label class="checkrow field full"><input type="checkbox" required><span>He leído la <button type="button" class="linkbtn" data-act="guide">guía de participación</button> y acepto sus reglas.</span></label>`:''}</div><div id="auth-error"></div><button class="btn" type="submit">${reg?'Enviar solicitud':'Iniciar sesión'}</button></form><div class="switch">${reg?'¿Ya tienes cuenta?':'¿Aún no tienes cuenta?'} <button class="linkbtn" data-act="authswitch">${reg?'Inicia sesión':'Solicitar cuenta'}</button></div><div class="authfooter"><button class="linkbtn" data-act="guide">Cómo funciona</button><button class="iconbtn" data-act="theme" aria-label="Cambiar tema">◐</button></div></div></section></main>`;}
function render(){if(!S.session||!S.data)return renderAuth();const d=S.data,p=d.profile;if(p.status!=='approved'){$('#app').innerHTML=`<main class="authform" style="min-height:100vh"><div class="card stack" style="max-width:480px"><span class="logo">▦</span><h1>Hola, ${esc(p.name.split(' ')[0])}</h1><p class="muted">${p.status==='pending'?'Tu solicitud está pendiente. Billy debe aprobarla para que puedas entrar a los cuadros.':p.status==='rejected'?'Tu solicitud no fue aprobada. Contacta a Billy si necesitas revisarla.':'Tu acceso está suspendido. Contacta a Billy.'}</p><button class="btn" data-act="refresh">Consultar estado</button><button class="btn ghost" data-act="logout">Cerrar sesión</button></div></main>`;return;}
const unread=(d.notices||[]).filter(n=>!n.read_at).length;const nav=(mobile=false)=>navs.map(([r,i,n])=>`<button class="${mobile?'':'navitem '}${S.route===r?'active':''}" data-route="${r}"><span class="navicon">${i}</span>${n}${r==='notices'&&unread?` <span class="badge">${unread}</span>`:''}</button>`).join('');
$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="row"><span class="logo">▦</span><span class="brand">Cuadros<small>POR BILLY</small></span></div><nav aria-label="Principal">${nav()}${admin()?`<button class="navitem ${S.route==='admin'?'active':''}" data-route="admin"><span class="navicon">⚙</span>Administración</button>`:''}<button class="navitem ${S.route==='guide'?'active':''}" data-route="guide"><span class="navicon">?</span>Guía del cuadro</button></nav><div class="sidefoot"><p>${esc(p.name)}</p><button class="linkbtn spacer" data-act="logout">Cerrar sesión</button></div></aside><main class="workspace"><header class="topbar"><div class="mobilebrand row"><span class="logo">▦</span><span class="brand">Cuadros</span></div><div class="greeting"><span class="eyebrow">${admin()?'ADMINISTRACIÓN':'TU ESPACIO'}</span><p class="smalltext muted">Hola, ${esc(p.name.split(' ')[0])}</p></div><div class="row"><span class="date">${new Intl.DateTimeFormat('es-EC',{timeZone:'America/Guayaquil',weekday:'long',day:'numeric',month:'long'}).format(new Date())}</span><button class="iconbtn" data-act="theme" aria-label="Cambiar tema">◐</button>${admin()?'<button class="iconbtn" data-route="admin" aria-label="Administración">⚙</button>':''}<button class="avatar" data-route="profile" aria-label="Mi cuenta">${esc(p.name[0])}</button></div></header><div id="content">${S.detail?detailPage(S.detail):S.route==='explore'?explore():S.route==='mine'?mine():S.route==='prizes'?prizesPage():S.route==='notices'?noticesPage():S.route==='profile'?profilePage():S.route==='admin'&&admin()?adminPage():guidePage()}</div></main><nav class="bottomnav" aria-label="Principal">${nav(true)}</nav></div>`;
}
function cuadroCard(c,m=null){const status=c.state;const current=Math.max(0,Math.min(c.weeks,Math.floor((time()-new Date(c.start_at))/604800000)+1));const own=m&&m.status==='active';return `<article class="card cuadro"><div class="cap"></div><div class="row between"><span class="eyebrow">CUADRO N.º ${c.number}</span><span class="badge ${status==='active'?'green':status==='scheduled'?'blue':''}">${stateName[status]}</span></div><h2>${esc(c.name)}</h2><div><div class="money">${money(c.contribution_cents*c.weeks)}</div><p class="muted smalltext">Recibes en tu turno</p></div><div class="data2"><div><span class="muted smalltext">Aporte semanal</span><strong>${money(c.contribution_cents)}</strong></div><div><span class="muted smalltext">Duración</span><strong>${c.weeks} semanas</strong></div></div>${own?`<div class="row between"><span class="badge">Tu turno: ${m.number}</span><span class="smalltext muted">Semana ${current} de ${c.weeks}</span></div><div class="progress"><i style="width:${current/c.weeks*100}%"></i></div>`:`<div><div class="row between smalltext"><span>Turnos asignados</span><strong>${c.assigned_count} / ${c.weeks}</strong></div><div class="progress"><i style="width:${c.assigned_count/c.weeks*100}%"></i></div><span class="muted tiny">Incluye ${c.reserved_count} turnos reservados por administración.</span></div>`}<div class="row between smalltext"><span class="muted">Multa por día</span><strong>${money(Math.round(c.contribution_cents*c.weeks*.005))}</strong></div><button class="btn ${own?'secondary':''}" data-act="detail" data-id="${c.id}">${own?'Ver mis semanas':'Ver cuadro'}</button></article>`}
function explore(){let cs=S.data.cuadros;if(S.filter!=='all')cs=cs.filter(c=>c.state===S.filter);return head('Encuentra tu próximo cuadro','Elige tu aporte y sigue el camino hasta tu turno.',admin()?'<button class="btn" data-act="create">＋ Crear cuadro</button>':'')+`<div class="tabs">${[['all','Todos'],['open','Abiertos'],['active','En marcha'],['finished','Finalizados']].map(([x,n])=>`<button class="tab ${S.filter===x?'active':''}" data-filter="${x}">${n}</button>`).join('')}</div>`+(cs.length?`<div class="grid">${cs.map(c=>cuadroCard(c,S.data.members.find(m=>m.cuadro_id===c.id&&m.user_id===S.data.profile.id))).join('')}</div>`:empty('Todavía no hay cuadros aquí',admin()?'Crea el primero y elige cuándo publicarlo.':'Cuando Billy publique un cuadro, podrás consultar sus reglas y solicitar tu turno.',admin()?'<button class="btn" data-act="create">Crear primer cuadro</button>':''));}
function mine(){const ms=S.data.members.filter(m=>m.user_id===S.data.profile.id&&m.status!=='left');const os=S.data.obligations.filter(o=>ms.some(m=>m.id===o.member_id));const paid=os.filter(o=>o.settled_at).length;const due=os.reduce((s,o)=>s+Number(o.due_cents),0);return head('Mis cuadros','Tus turnos y aportes, sin perderte entre otros cuadros.')+`<div class="stats"><div class="card"><span class="smalltext muted">Cuadros</span><strong>${ms.length}</strong></div><div class="card"><span class="smalltext muted">Semanas pagadas</span><strong>${paid}</strong></div><div class="card"><span class="smalltext muted">Pendiente</span><strong>${money(due)}</strong></div></div>`+(ms.length?`<div class="grid">${ms.map(m=>cuadroCard(S.data.cuadros.find(c=>c.id===m.cuadro_id),m)).join('')}</div>`:empty('Tu siguiente turno empieza aquí','Entra a un cuadro abierto para ver aquí tus semanas y comprobantes.','<button class="btn" data-route="explore">Explorar cuadros</button>'));}
function detailPage(id){const c=S.data.cuadros.find(c=>c.id===id);if(!c)return empty('Cuadro no disponible','Actualiza para consultar los cuadros.');const m=S.data.members.find(m=>m.cuadro_id===id&&m.user_id===S.data.profile.id);const active=m?.status==='active';const started=time()>=+new Date(c.start_at);const current=Math.max(0,Math.min(c.weeks,Math.floor((time()-new Date(c.start_at))/604800000)+1));const os=m?S.data.obligations.filter(o=>o.member_id===m.id):[];const transfer=m?S.data.transfers.find(t=>t.member_id===m.id&&t.kind==='payout'):null;return `<button class="btn ghost small" data-act="back">Volver</button><div class="spacer">${head('Cuadro n.º '+c.number+' · '+esc(c.name),stateName[c.state])}</div>${m?`<div class="card turnhero"><div><p class="muted smalltext">${m.status==='abandoned'?'Salida registrada':'Tu próxima meta'}</p><h2>${m.status==='abandoned'?'Devolución al finalizar':m.payout_at?'Tu turno ya fue entregado':'Recibir '+money(c.weeks*c.contribution_cents)}</h2><p class="muted smalltext spacer">${m.status==='abandoned'?'Se descontarán las multas pendientes.':'Entrega desde el domingo '+date(new Date(+new Date(c.start_at)+(m.number-1)*604800000+36*3600000))}</p></div><div class="turnnumber"><small>Tu turno</small><strong>${m.number}</strong></div></div>`:''}<div class="stats"><div class="card"><span class="smalltext muted">Aporte semanal</span><strong>${money(c.contribution_cents)}</strong></div><div class="card"><span class="smalltext muted">Duración</span><strong>${c.weeks} sem.</strong></div><div class="card"><span class="smalltext muted">Multa diaria</span><strong>${money(Math.round(c.weeks*c.contribution_cents*.005))}</strong></div></div><div class="noticebox"><strong>Antes de participar</strong><br>Los números se asignan al azar entre los turnos habilitados. Hay ${c.reserved_count} turnos reservados o cubiertos por la administración. Billy garantiza la entrega acordada; no hay necesariamente una persona por cada semana.<br>Pagas el sábado o antes del domingo a las 12:00. La entrega se realiza el domingo entre las 12:00 y las 23:59. ${c.state==='open'?'<br>Inicio de aportes: '+date(c.start_at,false)+'. El cierre puede adelantarse al ocuparse todos los cupos.':''}</div>${!active&&m?.status!=='abandoned'&&c.state==='open'?`<div class="spacer"><button class="btn" data-act="join" data-id="${c.id}">${m?'Volver a entrar al cuadro':'Entrar al cuadro'}</button>${m?`<p class="muted smalltext spacer">Reingresar añade una penalización de ${money(Math.round(c.weeks*c.contribution_cents*.005))}. Recuperas tu número si sigue libre.</p>`:''}</div>`:''}${m&&m.status!=='left'?`<div class="row between sectiontitle"><h2>Tu camino semanal</h2><div class="row"><button class="iconbtn" data-act="scrollweeks" data-dir="-1" aria-label="Semanas anteriores">‹</button><button class="iconbtn" data-act="scrollweeks" data-dir="1" aria-label="Semanas siguientes">›</button></div></div><div class="weektrack" id="weeks">${Array.from({length:c.weeks},(_,i)=>weekCard(c,m,i+1,os.find(o=>o.week===i+1),current,transfer)).join('')}</div>${S.data.transfers.filter(t=>t.member_id===m.id&&t.kind==='refund').map(t=>`<div class="card stack"><h3>Tu devolución</h3><p>Importe original: ${money(t.gross_cents)} · Descuentos: ${money(t.deducted_cents)} · Recibido: <strong>${money(t.net_cents)}</strong></p><p class="muted">${esc(t.note)}</p><button class="btn secondary" data-act="file" data-kind="transfer" data-id="${t.id}" ${t.deleted_at?'disabled':''}>${t.deleted_at?'Comprobante eliminado':'Ver comprobante'}</button></div>`).join('')}`:''}${active&&!m.payout_at&&c.state!=='finished'&&(started||c.state==='open')?`<button class="btn ghost spacer" data-act="leave" data-id="${c.id}">${started?'Abandonar cuadro':'Salir del cuadro'}</button>`:''}${admin()?`<div class="sectiontitle"><h2>Participantes reales</h2></div>${memberList(c)}`:''}`;}
function weekCard(c,m,w,o,current,transfer){const locked=w>current;const paid=o?.settled_at;const rs=o?S.data.receipts.filter(r=>r.obligation_id===o.id):[];const pending=rs.filter(r=>r.status==='pending').reduce((s,r)=>s+Number(r.amount_cents),0);const turn=w===m.number;return `<article class="card weekcard ${locked?'locked':w===current?'current':''}"><div class="row between"><span class="weeknum">${w}</span><span class="badge ${paid?'green':pending?'amber':locked?'':'blue'}">${paid?'Pagada':locked?'Bloqueada':pending?'En revisión':'Pendiente'}</span></div><div><h3>Semana ${w}</h3><p class="tiny muted">${date(new Date(+new Date(c.start_at)+(w-1)*604800000),false)}${turn?' · Tu turno':''}</p></div><div class="receiptlines"><div class="row between"><span>Aporte</span><span>${money(c.contribution_cents)}</span></div><div class="row between"><span>Multa ${o?.extra_cents?'+ reingreso':''}</span><span>${money(Number(o?.fine_cents||0)+Number(o?.extra_cents||0))}</span></div>${o?.accepted_cents?`<div class="row between"><span>Aceptado</span><span>${money(o.accepted_cents)}</span></div>`:''}<div class="row between total"><span>Pendiente</span><span>${money(o?.due_cents??c.contribution_cents)}</span></div></div>${!locked&&!paid&&o&&m.status==='active'?`<button class="btn small" data-act="receipt" data-id="${o.id}">${pending?'Subir otro comprobante':'Subir comprobante'}</button>`:locked?'<p class="smalltext muted">Se habilita al comenzar esta semana.</p>':paid?'<span class="smalltext" style="color:var(--green)">✓ Aporte completado</span>':'<p class="smalltext muted">Actualiza para consultar esta semana.</p>'}${rs.map(r=>`<div class="tiny"><span class="${r.status==='rejected'?'pendingreview':''}">${r.status==='accepted'?'Aceptado':r.status==='pending'?'En revisión':'Rechazado'} · ${money(r.amount_cents)}</span>${r.note?`<p>${esc(r.note)}</p>`:''}<button class="linkbtn" data-act="file" data-kind="receipt" data-id="${r.id}" ${r.deleted_at?'disabled':''}>${r.deleted_at?'Imagen eliminada':'Ver comprobante'}</button></div>`).join('')}${turn?`<div class="noticebox">${transfer?`Recibiste ${money(transfer.net_cents)}${transfer.deducted_cents?'<br>Descuentos: '+money(transfer.deducted_cents):''}<p>${esc(transfer.note)}</p><button class="linkbtn" data-act="file" data-kind="transfer" data-id="${transfer.id}" ${transfer.deleted_at?'disabled':''}>${transfer.deleted_at?'Imagen eliminada':'Ver tu transferencia'}</button>`:'Aquí aparecerá el comprobante de tu entrega.'}</div>`:''}</article>`;}
function noticesPage(){return head('Tus avisos','También quedan aquí si no activas las notificaciones del celular.','<button class="btn secondary small" data-act="read">Marcar leídos</button>')+`<div class="noticebox row between wrap"><span>Recibe avisos de nuevos cuadros, aportes y transferencias.</span><button class="btn small" data-act="push">Activar notificaciones</button></div><div class="list spacer">${S.data.notices.length?S.data.notices.map(n=>`<article class="listitem notice ${!n.read_at?'unread':''}"><span class="navicon">♧</span><div style="flex:1"><h3>${esc(n.title)}</h3><p class="muted smalltext">${esc(n.body)}</p><span class="tiny muted">${date(n.created_at)}</span>${n.cuadro_id?`<div class="spacer"><button class="linkbtn" data-act="detail" data-id="${n.cuadro_id}">Ver cuadro</button></div>`:''}</div></article>`).join(''):empty('Todo al día','Tus próximos avisos aparecerán aquí.')}</div>`;}
function prizesPage(){const total=Number(S.data.stats.available_cents);return head('Sorteo de multas','Cada 1 de enero, para todos los miembros aprobados.')+`<div class="card prizepool"><span class="eyebrow">FONDO ACUMULADO SIN REPARTIR</span><div class="money">${money(total)}</div><p class="muted">Solo incluye multas cobradas. El fondo acumulado se repartirá en el sorteo del 1 de enero.</p><p class="smalltext spacer">Cada $10 completos crea un premio. El sobrante se añade al primer premio. Si hay menos de $10, se entrega un solo premio.</p></div><h2 class="sectiontitle">Acumulado por cuadro</h2><div class="card tablewrap"><table><thead><tr><th>Cuadro</th><th>Multas cobradas</th><th>Sin repartir</th></tr></thead><tbody>${S.data.stats.by_cuadro.length?S.data.stats.by_cuadro.map(c=>`<tr><td>N.º ${c.number} · ${esc(c.name)}</td><td>${money(c.collected_cents)}</td><td>${money(c.available_cents)}</td></tr>`).join(''):'<tr><td colspan="3">Todavía no hay multas cobradas.</td></tr>'}</tbody></table></div><h2 class="sectiontitle">Ganadores y comprobantes</h2>${S.data.draws.length?S.data.draws.map(d=>`<div class="card spacer"><div class="row between"><h3>1 de enero de ${d.year}</h3><span class="badge">${money(d.total_cents)}</span></div><div class="list spacer">${S.data.prizes.filter(p=>p.draw_id===d.id).map(p=>`<div class="listitem"><div><span class="eyebrow">PREMIO ${p.position}</span><h3>${esc(p.winner_name)}</h3><span class="money" style="font-size:1.5rem">${money(p.amount_cents)}</span></div>${p.path?`<button class="btn secondary small" data-act="file" data-kind="prize" data-id="${p.id}">Ver comprobante</button>`:admin()?`<button class="btn small" data-act="prize" data-id="${p.id}">Registrar entrega</button>`:'<span class="badge amber">Entrega pendiente</span>'}</div>`).join('')}</div></div>`).join(''):empty('El próximo sorteo será el 1 de enero','Los ganadores y los comprobantes de sus premios se publicarán aquí.')}<p class="muted tiny spacer">Una persona no gana dos premios en el mismo sorteo. Si hay menos miembros elegibles que premios, el excedente se añade al primer premio.</p>`;}
function bankCard(b,manage=false){return `<article class="card stack"><div class="row between"><h3>${esc(b.bank)}</h3><span class="badge">${esc(b.account_type)}</span></div><p class="banknumber">${esc(b.account_number)}</p><p class="muted smalltext">${esc(b.holder)}${b.identity_number?'<br>Cédula: '+esc(b.identity_number):''}${b.email?'<br>'+esc(b.email):''}</p><div class="row"><button class="btn secondary small" data-act="copy" data-value="${esc(b.account_number)}">Copiar cuenta</button>${manage?`<button class="btn ghost small" data-act="bankedit" data-id="${b.id}">Editar</button>`:''}</div></article>`;}
function profilePage(){const p=S.data.profile;const own=S.data.banks.filter(b=>b.owner_id===p.id&&b.active);return head('Mi cuenta','Tus datos y preferencias.')+`<div class="admincards"><div class="card"><h2>Tus datos</h2><form id="profile-form" class="stack spacer"><label class="field">Nombre completo<input name="name" value="${esc(p.name)}" required></label><label class="field">Celular<input name="phone" value="${esc(p.phone)}" type="tel" required></label><label class="field">Cédula<input name="identity_number" value="${esc(p.identity_number)}"></label><label class="field">Empresa o referencia<input name="company" value="${esc(p.company)}"></label><p class="smalltext muted">${esc(p.email)}</p><button class="btn" type="submit">Guardar datos</button></form></div><div class="card stack"><h2>Tu aplicación</h2><button class="btn secondary" data-act="push">Activar notificaciones</button><button class="btn ghost" data-act="install">Instalar versión web</button><button class="btn ghost" data-act="theme">Cambiar modo claro / oscuro</button><button class="btn ghost" data-act="password">Cambiar contraseña</button><button class="btn ghost" data-route="guide">Guía de participación</button><button class="btn ghost" data-act="logout">Cerrar sesión</button></div></div><div class="row between sectiontitle"><h2>Mis cuentas bancarias</h2>${own.length<2?'<button class="btn secondary small" data-act="bankadd">＋ Añadir cuenta</button>':''}</div><p class="muted smalltext">Una cuenta principal y una opcional de respaldo para recibir tu turno.</p><div class="grid spacer">${own.map(b=>bankCard(b,true)).join('')}</div><h2 class="sectiontitle">Cuentas para aportar</h2><div class="grid">${S.data.banks.filter(b=>b.owner_id===null&&b.active).map(b=>bankCard(b)).join('')||empty('Billy aún no registró cuentas','Consulta antes de realizar tu primer depósito.')}</div>`;}
function memberList(c){const ms=S.data.members.filter(m=>m.cuadro_id===c.id&&m.status!=='left');return `<div class="list">${ms.map(m=>{const p=S.data.profiles.find(p=>p.id===m.user_id);const os=S.data.obligations.filter(o=>o.member_id===m.id);return `<div class="listitem"><div><h3>${esc(p?.name||'Miembro')} <span class="badge">Turno ${m.number}</span></h3><p class="smalltext muted">${m.status==='abandoned'?'Abandonó · devolución al finalizar':m.payout_at?'Turno entregado':'Turno pendiente'} · Debe ${money(os.reduce((s,o)=>s+Number(o.due_cents),0))}</p>${p?.phone?`<p class="tiny muted">${esc(p.phone)}</p>`:''}</div><div class="actions">${m.status==='active'&&!m.payout_at?`<button class="btn secondary small" data-act="transfer" data-id="${m.id}" data-kind="payout">Registrar entrega</button>`:''}${m.status==='abandoned'?`<button class="btn secondary small" data-act="transfer" data-id="${m.id}" data-kind="refund">Registrar devolución</button>`:''}<button class="btn ghost small" data-act="memberdebts" data-id="${m.id}">Aportes</button></div></div>`}).join('')||empty('Aún no hay participantes reales','Las posiciones reservadas quedan bajo tu responsabilidad.')}</div>`;}
function adminPage(){const pending=S.data.receipts.filter(r=>r.status==='pending');const waiting=S.data.profiles.filter(p=>p.status==='pending');return head('Administración','Cuadros, pagos y miembros bajo tu control.','<button class="btn" data-act="create">＋ Crear cuadro</button>')+`<div class="stats"><div class="card"><span class="smalltext muted">Por revisar</span><strong>${pending.length}</strong></div><div class="card"><span class="smalltext muted">Solicitudes</span><strong>${waiting.length}</strong></div><div class="card"><span class="smalltext muted">En marcha</span><strong>${S.data.cuadros.filter(c=>c.state==='active').length}</strong></div></div><div class="tabs">${[['cuadros','Cuadros'],['receipts','Comprobantes'],['users','Miembros'],['banks','Mis cuentas para recibir'],['draws','Sorteo anual']].map(([v,n])=>`<button class="tab ${S.adminTab===v?'active':''}" data-admin="${v}">${n}</button>`).join('')}</div>${S.adminTab==='cuadros'?`<div class="grid">${S.data.cuadros.map(c=>cuadroCard(c)).join('')||empty('Crea tu primer cuadro','Elige semanas, aporte y números habilitados.')}</div>`:S.adminTab==='receipts'?`<div class="list">${pending.map(r=>{const p=S.data.profiles.find(p=>p.id===r.user_id);const o=S.data.obligations.find(o=>o.id===r.obligation_id);const m=S.data.members.find(m=>m.id===o?.member_id);const c=S.data.cuadros.find(c=>c.id===m?.cuadro_id);return `<div class="listitem"><div><h3>${esc(p?.name)} · ${money(r.amount_cents)}</h3><p class="smalltext muted">N.º ${c?.number} · ${esc(c?.name)} · Semana ${o?.week}</p><p class="tiny muted">Presentado: ${date(r.submitted_at)}</p></div><div class="actions"><button class="btn ghost small" data-act="file" data-kind="receipt" data-id="${r.id}">Ver comprobante</button><button class="btn small" data-act="review" data-id="${r.id}" data-accept="true">Aceptar</button><button class="btn secondary small" data-act="review" data-id="${r.id}" data-accept="false">Solicitar corrección</button></div></div>`}).join('')||empty('No tienes comprobantes pendientes','Cada comprobante nuevo llegará también a tus avisos.')}</div>`:S.adminTab==='users'?`<div class="list">${S.data.profiles.filter(p=>p.role!=='admin').map(p=>`<div class="listitem"><div><h3>${esc(p.name)} <span class="badge ${p.status==='approved'?'green':'amber'}">${({pending:'Pendiente',approved:'Aprobado',rejected:'Rechazado',suspended:'Suspendido'})[p.status]}</span></h3><p class="smalltext muted">${esc(p.email)} · ${esc(p.phone)}</p><p class="tiny muted">${esc(p.company)} · Cédula ${esc(p.identity_number)}</p></div><div class="actions">${p.status!=='approved'?`<button class="btn small" data-act="approve" data-id="${p.id}" data-status="approved">Aprobar</button>`:`<button class="btn ghost small" data-act="approve" data-id="${p.id}" data-status="suspended">Suspender</button>`}${p.status==='pending'?`<button class="btn secondary small" data-act="approve" data-id="${p.id}" data-status="rejected">Rechazar</button>`:''}<button class="btn ghost small" data-act="reset" data-id="${p.id}">Restablecer acceso</button></div></div>`).join('')||empty('Sin solicitudes por ahora','Los miembros podrán solicitar una cuenta desde el inicio de sesión.')}</div>`:S.adminTab==='banks'?`<button class="btn secondary" data-act="adminbank">＋ Añadir cuenta para recibir aportes</button><div class="grid spacer">${S.data.banks.filter(b=>b.owner_id===null&&b.active).map(b=>bankCard(b,true)).join('')}</div>`:`<div class="noticebox">El sorteo se ejecuta automáticamente el 1 de enero. Aquí puedes consultar los premios y registrar sus transferencias.</div><button class="btn secondary spacer" data-act="draw">Comprobar sorteo del 1 de enero</button><div class="spacer">${prizesPage()}</div>`}`;}
function guidePage(){return head('Guía del cuadro','Las reglas, antes de comprometerte.')+guideContent();}
function guideContent(){return `<div class="guide"><div class="noticebox">Todas las horas corresponden a Ecuador, zona America/Guayaquil. Participa únicamente si puedes completar tus aportes durante todo el cuadro.</div>${[
['1. Cuenta y participación','Solicita tu cuenta con nombre, cédula, celular, correo, contraseña y una cuenta bancaria principal. Billy revisa tu solicitud. Puedes añadir una cuenta de respaldo. Cada persona puede participar en varios cuadros, con un solo número en cada uno.'],
['2. Turnos reservados y sorteo','La administración puede reservar posiciones iniciales, finales o intermedias. Tu número se asigna al azar únicamente entre los turnos habilitados que estén libres. La barra muestra turnos asignados e incluye reservas administrativas, no necesariamente personas. Los números libres concretos no se muestran. Billy cubre y garantiza las posiciones sin beneficiario, incluso si quedan cupos sin ocupar al cerrar.'],
['3. Inscripciones y semana cero','La semana cero es para inscribirse. El cierre ocurre al ocuparse todos los cupos habilitados o en una hora programada al azar del jueves o viernes entre las 05:00 y las 20:00. Recibirás un aviso de cierre. Los aportes comienzan el sábado siguiente. No puedes pagar semanas futuras.'],
['4. Aportes y multas','Deposita el sábado o antes de las 12:00 del domingo en cualquiera de las cuentas administrativas disponibles y sube el comprobante completo. Desde el domingo a las 12:00 se añade una multa diaria del 0,5 % de la entrega total. Cada 24 horas se añade otro 0,5 %, sin interés compuesto. Ejemplo: 10 semanas × $10 = $100 de entrega; multa diaria $0,50. Un pago parcial no completa la cuota: si pagas $5 el sábado y terminas el domingo después del mediodía, restan $5 más $0,50. La multa aumenta hasta completar el pago o finalizar el cuadro; Billy puede detenerla manualmente. La deuda no desaparece al finalizar.'],
['5. Revisión de comprobantes','Solo Billy recibe el aviso de tu comprobante y verifica el movimiento bancario. Cuenta la fecha y hora de presentación del comprobante válido, aunque lo revise después. Si la imagen no está clara y puede verificar el dinero completo, puede aceptarla. Un comprobante rechazado o un pago incompleto mantiene la obligación pendiente.'],
['6. Entrega de tu turno','La entrega se realiza el domingo de tu turno, desde las 12:00 hasta las 23:59. Billy puede atender varios cuadros; no se promete una hora exacta dentro de esa ventana. En tu semana de turno debes aportar igualmente. Verás tu comprobante de aporte y, por separado, el de la transferencia de Billy. Si hay descuentos por multas pendientes de cuadros anteriores, se mostrarán el importe original, el descuento y el neto enviado.'],
['7. Salida, abandono y reingreso','Puedes salir antes del cierre de inscripciones. Si vuelves a entrar antes del cierre, se añade una penalización del 0,5 % de la entrega: recuperas tu número si está libre; de lo contrario, recibes otro habilitado al azar. Durante el cuadro, si aún no recibiste tu turno, puedes confirmar el abandono mediante el botón correspondiente. Dejar de pagar no cuenta como abandono. Al abandonar se detienen nuevas multas; las ya generadas siguen pendientes. Tus aportes se devuelven al terminar el cuadro, descontando multas. Si ya recibiste tu turno, no puedes retirarte y debes completar los aportes.'],
['8. Fondo de multas y sorteo anual','Todos los miembros aprobados, aunque no hayan participado en cuadros, son elegibles para el sorteo del 1 de enero. El fondo muestra multas efectivamente cobradas por cuadro y su total pendiente de reparto. Con $19,99 hay un premio; con $20, dos de $10; con $27, uno de $17 y otro de $10. Los premios siguientes son de $10 y el sobrante va al primero. No se repite ganador en el mismo sorteo; si faltan miembros elegibles, el exceso se suma al primer premio. El dinero acumulado de las multas se destina a los premios del sorteo anual. Los ganadores y comprobantes de premios son visibles para los miembros aprobados.'],
['9. Notificaciones y comprobantes guardados','Aceptar notificaciones es recomendable y voluntario. Se avisa de cuadros nuevos, cierres, semanas activas, multas pendientes, transferencias y sorteos. Solo recibes recordatorios de pago de los cuadros a los que perteneces. Los avisos también quedan en la campanita aunque no tengas permiso de notificaciones. Las imágenes y PDF de aportes y entregas se eliminan siete días después del fin del cuadro; los registros de dinero se conservan. Descarga tus comprobantes antes de ese plazo si quieres conservarlos.']
].map(([h,p])=>`<details><summary>${h}</summary><p>${p}</p></details>`).join('')}</div>`;}
function joinModal(id){const c=S.data.cuadros.find(c=>c.id===id);const m=S.data.members.find(m=>m.cuadro_id===id&&m.user_id===S.data.profile.id);modal('Confirmar participación',`<div class="stack"><h3>N.º ${c.number} · ${esc(c.name)}</h3><p>Aportarás <strong>${money(c.contribution_cents)}</strong> cada semana durante <strong>${c.weeks} semanas</strong>. Recibirás <strong>${money(c.weeks*c.contribution_cents)}</strong> en tu turno.</p><div class="noticebox">Tu número se sortea únicamente entre los turnos habilitados. Hay turnos reservados por administración. Multa diaria: ${money(Math.round(c.weeks*c.contribution_cents*.005))}.${m?'<br>Reingreso: '+money(Math.round(c.weeks*c.contribution_cents*.005))+'.':''}</div><label class="checkrow"><input id="join-accept" type="checkbox"><span>Leí la guía y acepto completar los aportes incluso después de recibir mi turno.</span></label></div>`,`<button class="btn ghost" data-act="close">Cancelar</button><button class="btn" data-act="confirmjoin" data-id="${id}">Aceptar y obtener turno</button>`);}
function bankModal(b=null,adminBank=false){modal(b?'Editar cuenta':'Añadir cuenta',`<form id="bank-form" data-id="${b?.id||''}" data-admin="${adminBank}"><div class="formgrid">${bankFields(b||{holder:S.data.profile.name})}<label class="checkrow field full"><input type="checkbox" name="is_primary" ${!b||b.is_primary?'checked':''}><span>Cuenta principal</span></label>${b?'<label class="checkrow field full"><input type="checkbox" name="active" '+(b.active?'checked':'')+'><span>Cuenta activa</span></label>':''}</div><footer><button class="btn" type="submit">Guardar cuenta</button></footer></form>`);}
function nextSaturday(){const d=new Date(Date.now()-5*3600000);let add=(6-d.getUTCDay()+7)%7;if(!add&&d.getUTCHours()>=1)add=7;return new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate()+add,1)).toISOString().slice(0,16)}
function createModal(){modal('Crear un cuadro',`<form id="create-form"><div class="formgrid"><label class="field full">Nombre del cuadro<input name="name" placeholder="Ej. Navidad" required maxlength="160"></label><label class="field">Semanas / números<input type="number" name="weeks" id="create-weeks" value="10" min="2" max="104" required></label><label class="field">Aporte semanal ($)<input type="number" name="amount" id="create-amount" value="10" min="0.01" max="1000000" step="0.01" required></label><div id="create-calculation" class="noticebox field full"></div><label class="field full">Publicación<select name="mode" id="publish-mode"><option value="scheduled">Programar publicación</option><option value="now">Publicar ahora</option></select></label><label class="field full" id="publish-field">Fecha y hora en Ecuador<input name="publish_at" type="datetime-local" value="${nextSaturday()}" required></label><div class="field full"><span>Números habilitados para miembros</span><p class="muted smalltext">Desmarca los turnos que reservas para ti. Los miembros no ven cuáles son.</p><div id="create-numbers" class="numbers"></div></div><label class="checkrow field full"><input type="checkbox" required><span>Asumo la entrega completa y la cobertura de los turnos sin beneficiario.</span></label></div><footer><button class="btn" type="submit">Crear cuadro</button></footer></form>`);updateCreate(true);}
function updateCreate(reset=false){const w=Math.max(2,Math.min(104,Number($('#create-weeks').value)||2)),a=dollars($('#create-amount').value);$('#create-calculation').innerHTML=`Entrega por turno: <strong>${money(w*a)}</strong><br>Multa diaria (0,5 %): <strong>${money(Math.round(w*a*.005))}</strong>`;if(reset||$('#create-numbers').children.length!==w)$('#create-numbers').innerHTML=Array.from({length:w},(_,i)=>`<label class="numberpick"><input name="enabled" type="checkbox" value="${i+1}" checked><span>${i+1}</span></label>`).join('');}
function receiptModal(id){const o=S.data.obligations.find(o=>o.id===id);const bs=S.data.banks.filter(b=>b.owner_id===null&&b.active);modal('Tu recibo · Semana '+o.week,`<form id="receipt-form" data-id="${id}" class="stack"><div class="receiptlines"><div class="row between"><span>Aporte</span><strong>${money(o.base_cents)}</strong></div><div class="row between"><span>Multa y reingreso</span><strong>${money(Number(o.fine_cents)+Number(o.extra_cents))}</strong></div><div class="row between"><span>Ya aceptado</span><strong>${money(o.accepted_cents)}</strong></div><div class="row between total"><span>Pendiente por pagar</span><strong>${money(o.due_cents)}</strong></div></div><label class="field">Cuenta a la que depositaste<select name="bank_id" id="receipt-bank" required><option value="">Selecciona una cuenta</option>${bs.map(b=>`<option value="${b.id}">${esc(b.bank)} · ${esc(b.account_type)} · ${esc(b.account_number)}</option>`).join('')}</select></label><div id="receipt-bank-info"></div>${!bs.length?'<div class="errorbox">Billy debe registrar una cuenta bancaria antes de recibir aportes.</div>':''}<label class="field">Cantidad de este comprobante ($)<input name="amount" type="number" min="0.01" step="0.01" value="${(o.due_cents/100).toFixed(2)}" required></label><p class="muted smalltext">Si envías una parte, la cuota sigue pendiente y puede generar multa. Completa el saldo con otro comprobante.</p><label class="field">Comprobante<input class="fileinput" name="file" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" required><span class="muted tiny">Imagen o PDF, máximo 5 MB.</span></label><footer><button class="btn" type="submit" ${!bs.length?'disabled':''}>Enviar a revisión</button></footer></form>`);}
function finePending(o){const paid=S.data.ledger.filter(l=>l.obligation_id===o.id&&['fine','deduction'].includes(l.kind)).reduce((s,l)=>s+Number(l.amount_cents),0);return Math.max(0,Number(o.fine_cents)+Number(o.extra_cents)-paid)}
function transferModal(mid,kind){const m=S.data.members.find(m=>m.id===mid),p=S.data.profiles.find(p=>p.id===m.user_id),c=S.data.cuadros.find(c=>c.id===m.cuadro_id);const banks=S.data.banks.filter(b=>b.owner_id===m.user_id&&b.active);const gross=kind==='payout'?c.weeks*c.contribution_cents:S.data.ledger.filter(l=>l.user_id===m.user_id&&l.cuadro_id===c.id&&l.kind==='principal').reduce((s,l)=>s+Number(l.amount_cents),0);const debts=S.data.obligations.filter(o=>{const mm=S.data.members.find(mm=>mm.id===o.member_id),cc=S.data.cuadros.find(cc=>cc.id===mm?.cuadro_id);return mm?.user_id===m.user_id&&finePending(o)>0&&(kind==='refund'&&mm.id===m.id||cc?.state==='finished')});modal(kind==='payout'?'Registrar entrega':'Registrar devolución',`<form id="transfer-form" data-id="${mid}" data-kind="${kind}" data-gross="${gross}" class="stack"><h3>${esc(p.name)} · Turno ${m.number}</h3><p>Cuadro n.º ${c.number} · ${esc(c.name)}</p><div class="grid">${banks.map(b=>bankCard(b)).join('')||'<div class="errorbox">No hay cuenta bancaria activa del beneficiario.</div>'}</div><div class="noticebox">Importe original: <strong>${money(gross)}</strong><div id="transfer-net"></div></div>${debts.length?`<h3>Multas pendientes para descontar</h3>${debts.map(o=>{const mm=S.data.members.find(mm=>mm.id===o.member_id),cc=S.data.cuadros.find(cc=>cc.id===mm.cuadro_id);return `<label class="checkrow"><input name="deduction" type="checkbox" value="${o.id}" data-amount="${finePending(o)}" ${kind==='refund'&&mm.id===m.id?'checked disabled':''}><span>Cuadro n.º ${cc.number} · Semana ${o.week}: ${money(finePending(o))}</span></label>`}).join('')}`:''}<label class="field">Detalle de la transferencia<textarea name="note" maxlength="500" placeholder="Indica los descuentos y el cuadro de origen."></textarea></label><label class="field">Comprobante de tu transferencia<input class="fileinput" name="file" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" required></label><label class="checkrow"><input type="checkbox" required><span>Transferí exactamente el importe neto indicado.</span></label><footer><button class="btn" type="submit">Registrar transferencia</button></footer></form>`);updateNet();}
function updateNet(){const f=$('#transfer-form');if(!f)return;const sum=[...f.querySelectorAll('[name=deduction]:checked')].reduce((s,i)=>s+Number(i.dataset.amount),0);const capped=Math.min(sum,Number(f.dataset.gross));$('#transfer-net').innerHTML=`Descuentos: ${money(capped)}<br><strong>Debes transferir: ${money(Number(f.dataset.gross)-capped)}</strong>`;}
async function upload(file){if(!file||file.size>5242880)throw Error('Sube un comprobante de máximo 5 MB');const s=await api('prepare_upload',{mime:file.type,size:file.size});const r=await fetch(s.signedUrl,{method:'PUT',headers:{'Content-Type':file.type},body:file});if(!r.ok)throw Error('No se pudo subir el archivo. Intenta nuevamente.');return s.path;}
async function push(){if(!('serviceWorker'in navigator)||!('PushManager'in window))throw Error('Este navegador no admite avisos push. Instala la aplicación o usa Chrome en Android.');const permission=await Notification.requestPermission();if(permission!=='granted'){toast('Puedes consultar todos los avisos dentro de la aplicación.');return;}const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(!sub){const s=S.data.vapid_public;const b=atob(s.replace(/-/g,'+').replace(/_/g,'/'));sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(b,c=>c.charCodeAt(0))});}await api('push',{subscription:sub.toJSON()});toast('Notificaciones activadas en este celular');}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-act],[data-route],[data-filter],[data-admin]');if(!el)return;if(el.dataset.route){setRoute(el.dataset.route);return;}if(el.dataset.filter){S.filter=el.dataset.filter;render();return;}if(el.dataset.admin){S.adminTab=el.dataset.admin;render();return;}const act=el.dataset.act;try{if(act==='close')return closeModal();if(act==='theme'){const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;localStorage.setItem('cuadros-theme',t);return;}if(act==='authswitch'){S.authMode=S.authMode==='login'?'register':'login';render();return;}if(act==='guide'){modal('Guía de participación',guideContent());return;}if(act==='detail'){S.detail=el.dataset.id;render();window.scrollTo(0,0);return;}if(act==='back'){S.detail=null;render();return;}if(act==='scrollweeks'){$('#weeks')?.scrollBy({left:Number(el.dataset.dir)*265,behavior:'smooth'});return;}if(act==='create')return createModal();if(act==='join')return joinModal(el.dataset.id);if(act==='bankadd')return bankModal();if(act==='adminbank')return bankModal(null,true);if(act==='bankedit'){const b=S.data.banks.find(b=>b.id===el.dataset.id);return bankModal(b,b.owner_id===null);}if(act==='receipt'){await load();return receiptModal(el.dataset.id);}if(act==='transfer')return transferModal(el.dataset.id,el.dataset.kind);if(act==='memberdebts'){const m=S.data.members.find(m=>m.id===el.dataset.id);modal('Aportes y multas',`<div class="list">${S.data.obligations.filter(o=>o.member_id===m.id).map(o=>`<div class="listitem"><div><h3>Semana ${o.week}</h3><p>Pendiente ${money(o.due_cents)} · Multa ${money(o.fine_cents)}</p></div>${!o.fine_stopped_at&&!o.settled_at?`<button class="btn ghost small" data-act="stopfine" data-id="${o.id}">Detener multa</button>`:''}</div>`).join('')||'<p>Los aportes se habilitarán al comenzar el cuadro.</p>'}</div>`);return;}
if(act==='password'||act==='reset'){modal(act==='reset'?'Restablecer contraseña':'Cambiar contraseña',`<form id="password-form" data-user="${el.dataset.id||''}" class="stack"><label class="field">Nueva contraseña<input name="password" type="password" autocomplete="new-password" minlength="10" required></label><label class="field">Repite la contraseña<input name="confirm" type="password" minlength="10" required></label><footer><button class="btn" type="submit">Guardar contraseña</button></footer></form>`);return;}
if(act==='prize'){modal('Registrar premio',`<form id="prize-form" data-id="${el.dataset.id}" class="stack"><p>Sube el comprobante de la transferencia. Será visible para todos los miembros aprobados.</p><input class="fileinput" name="file" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" required><footer><button class="btn" type="submit">Publicar comprobante</button></footer></form>`);return;}
if(act==='review'){const yes=el.dataset.accept==='true';modal(yes?'Aceptar comprobante':'Solicitar corrección',`<form id="review-form" data-id="${el.dataset.id}" data-accept="${yes}" class="stack"><p>${yes?'Confirma que verificaste el ingreso real y la cantidad. Si es parcial, el saldo seguirá pendiente.':'El comprobante quedará rechazado. Explica qué debe corregir o cuánto falta.'}</p><label class="field">Observación<textarea name="note" maxlength="500" ${yes?'':'required'}></textarea></label><footer><button class="btn" type="submit">${yes?'Aceptar pago':'Enviar corrección'}</button></footer></form>`);return;}
if(act==='leave'){const c=S.data.cuadros.find(c=>c.id===el.dataset.id),m=S.data.members.find(m=>m.cuadro_id===c.id&&m.user_id===S.data.profile.id);const fines=S.data.obligations.filter(o=>o.member_id===m.id).reduce((s,o)=>s+finePending(o),0);modal('Confirmar salida',`<p>${time()<+new Date(c.start_at)?'Puedes volver antes del cierre con penalización de reingreso.':'Tus aportes se devolverán al finalizar el cuadro, descontando multas pendientes. Se detendrán nuevas multas al confirmar.'}</p><div class="noticebox spacer">Multas pendientes actuales: ${money(fines)}.</div>`,`<button class="btn ghost" data-act="close">Cancelar</button><button class="btn danger" data-act="confirmleave" data-id="${c.id}">Confirmar salida</button>`);return;}
if(act==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else modal('Instalar Cuadros',`<p>En Chrome para Android, abre el menú ⋮ y selecciona <strong>Instalar aplicación</strong> o <strong>Añadir a pantalla de inicio</strong>. En iPhone, usa Safari: Compartir → Añadir a pantalla de inicio.</p><p class="spacer">Se abrirá desde su icono con apariencia de aplicación. No necesitas descargar un APK.</p>`);return;}
if(act==='copy'){await navigator.clipboard.writeText(el.dataset.value);toast('Cuenta copiada');return;}if(act==='file'){el.disabled=true;const r=await api('file',{kind:el.dataset.kind,id:el.dataset.id});window.open(r.signedUrl,'_blank','noopener');el.disabled=false;return;}if(act==='push'){await push();return;}
if(act==='logout'){try{const reg=await navigator.serviceWorker.getRegistration();const sub=reg?await reg.pushManager.getSubscription():null;if(sub){await api('push_remove',{endpoint:sub.endpoint});await sub.unsubscribe()}}catch{}try{await auth('logout',{})}catch{}S.session=null;S.data=null;localStorage.removeItem('cuadros-session');render();return;}
el.disabled=true;if(act==='confirmjoin'){if(!$('#join-accept')?.checked)throw Error('Acepta las reglas antes de entrar');const m=await api('join',{cuadro_id:el.dataset.id});await load();modal('¡Ya tienes tu turno!',`<p>Tu número asignado es</p><div class="bigturn">${m.number}</div><p>Revisa tus semanas y recuerda completar todos los aportes.</p>`,`<button class="btn" data-act="close">Ver mi cuadro</button>`);return;}if(act==='confirmleave'){await api('leave',{cuadro_id:el.dataset.id});closeModal();toast('Salida registrada');}if(act==='approve'){await api('approve_user',{id:el.dataset.id,status:el.dataset.status});toast('Estado actualizado');}if(act==='stopfine'){await api('stop_fine',{id:el.dataset.id});closeModal();toast('Acumulación de multa detenida');}if(act==='read')await api('read_notices');if(act==='draw'){await api('draw');toast('Sorteo comprobado');}await load();}catch(err){toast(err.message);el.disabled=false;}});
document.addEventListener('change',e=>{if(e.target.id==='publish-mode'){$('#publish-field').style.display=e.target.value==='now'?'none':'grid';$('#publish-field input').required=e.target.value!=='now';}if(e.target.id==='receipt-bank'){const b=S.data.banks.find(b=>b.id===e.target.value);$('#receipt-bank-info').innerHTML=b?`<div class="noticebox">${esc(b.holder)} · ${esc(b.identity_number)}<br>${esc(b.account_number)} <button type="button" class="linkbtn" data-act="copy" data-value="${esc(b.account_number)}">Copiar cuenta</button></div>`:'';}if(e.target.name==='deduction')updateNet();});
document.addEventListener('input',e=>{if(e.target.id==='create-weeks'||e.target.id==='create-amount')updateCreate();});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const b=formObj(f),button=f.querySelector('[type=submit]');button.disabled=true;const before=button.textContent;button.textContent='Procesando…';try{
if(f.id==='auth-form'){if(S.authMode==='login'){saveSession(await auth('token?grant_type=password',{email:b.email,password:b.password}));await load();const cid=new URL(location.href).searchParams.get('cuadro');if(cid){S.detail=cid;render();}return;}await api('register',{...b,bank:{bank:b.bank,holder:b.holder,account_number:b.account_number,account_type:b.account_type,identity_number:b.bank_identity,email:b.bank_email}},true);S.authMode='login';render();toast('Solicitud enviada. Espera la aprobación de Billy.');return;}
if(f.id==='profile-form')await api('profile',b);
if(f.id==='bank-form')await api('bank',{id:f.dataset.id||null,admin_bank:f.dataset.admin==='true',bank:{bank:b.bank,account_type:b.account_type,account_number:b.account_number,holder:b.holder,identity_number:b.bank_identity,email:b.bank_email,is_primary:!!b.is_primary,active:f.dataset.id?!!b.active:true}});
if(f.id==='create-form'){const pub=b.mode==='now'?null:new Date(b.publish_at+'-05:00').toISOString();await api('create',{name:b.name,weeks:Number(b.weeks),contribution_cents:dollars(b.amount),enabled_numbers:new FormData(f).getAll('enabled').map(Number),publish_at:pub});toast('Cuadro creado');}
if(f.id==='receipt-form'){const path=await upload(f.elements.file.files[0]);await api('receipt',{obligation_id:f.dataset.id,amount_cents:dollars(b.amount),bank_id:b.bank_id,path});toast('Comprobante enviado a Billy');}
if(f.id==='review-form')await api('review',{id:f.dataset.id,accept:f.dataset.accept==='true',note:b.note});
if(f.id==='transfer-form'){const path=await upload(f.elements.file.files[0]);await api('transfer',{member_id:f.dataset.id,kind:f.dataset.kind,path,note:b.note,deduction_ids:[...f.querySelectorAll('[name=deduction]:checked')].map(i=>i.value)});toast('Transferencia registrada');}
if(f.id==='prize-form'){const path=await upload(f.elements.file.files[0]);await api('prize',{id:f.dataset.id,path});toast('Comprobante del premio publicado');}
if(f.id==='password-form'){if(b.password!==b.confirm)throw Error('Las contraseñas no coinciden');if(f.dataset.user)await api('reset_password',{id:f.dataset.user,password:b.password});else await auth('user',{password:b.password},'PUT');toast('Contraseña actualizada');}
closeModal();await load();if(f.id==='profile-form'||f.id==='bank-form')toast('Datos guardados');
}catch(err){if(f.id==='auth-form')$('#auth-error').innerHTML=`<div class="errorbox">${esc(err.message)}</div>`;else toast(err.message);button.disabled=false;button.textContent=before;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#modal-root .modal')){const els=[...$('#modal-root .modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,a')];if(!els.length)return;if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
window.addEventListener('offline',()=>toast('Sin conexión. Tus datos se actualizarán cuando vuelvas a conectarte.'));
window.addEventListener('online',()=>load().catch(e=>toast(e.message)));
document.documentElement.dataset.theme=localStorage.getItem('cuadros-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');
if('serviceWorker'in navigator)navigator.serviceWorker.register(new URL('./sw.js', import.meta.url)).catch(()=>{});
render();load().catch(e=>toast(e.message));
setInterval(()=>{if(S.session&&S.data?.profile.status==='approved'&&!$('#modal-root').children.length&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))load().catch(()=>{})},60000);
